def _c(title_en, title_ar, body_en, body_ar, f_en, cap_ar, f_ar, svg):
    return nafes_concept(title_en, title_ar, body_en, body_ar, f_en, cap_ar, f_ar, svg, svg)


def _ex_num(ex_id, t_en, t_ar, q_en, q_ar, ans, dist, sfx, idea_en, s_en, c_en, idea_ar, s_ar, c_ar, svg):
    return ext_worked_example(
        ex_id, t_en, t_ar, q_en, q_ar, idea_en, s_en, c_en, idea_ar, s_ar, c_ar,
        diagram_en=svg, diagram_ar=svg, correct_val=ans, distractors=dist, suffix=sfx,
    )


def _ex_bi(ex_id, t_en, t_ar, q_en, q_ar, pairs, idea_en, s_en, c_en, idea_ar, s_ar, c_ar, svg):
    return ext_worked_example(
        ex_id, t_en, t_ar, q_en, q_ar, idea_en, s_en, c_en, idea_ar, s_ar, c_ar,
        diagram_en=svg, diagram_ar=svg, bilingual_pairs=pairs,
    )


