def main() -> None:
    lessons = build_science_lessons()
    assert len(lessons) == 12
    attach_bank_ids_and_validate_lessons(
        lessons,
        bank_path=ROOT / "data" / "nafes_science.json",
        bp_key="nafes_science_blueprint",
        out_path=ROOT / "data" / "nafes_science_lessons.json",
    )


if __name__ == "__main__":
    main()
